"""Regenerate requirements.lock from requirements.in.

The lock pins the full resolved dependency closure so CI installs exactly what was
tested. Regenerate after any dependency change and commit both files.

    python scripts/generate_lock.py
"""

from __future__ import annotations

import json
import subprocess
import sys
import tempfile
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parents[1]
INPUT = REPO_ROOT / "requirements.in"
OUTPUT = REPO_ROOT / "requirements.lock"

HEADER = (
    "# Generated by scripts/generate_lock.py from requirements.in\n"
    "# Regenerate after changing dependencies; CI installs exactly this file.\n"
)


def main() -> int:
    if not INPUT.exists():
        print(f"missing {INPUT}", file=sys.stderr)
        return 2

    with tempfile.TemporaryDirectory() as tmp:
        report = Path(tmp) / "report.json"
        result = subprocess.run(
            [
                sys.executable,
                "-m",
                "pip",
                "install",
                "--dry-run",
                "--ignore-installed",
                "--quiet",
                "--report",
                str(report),
                "-r",
                str(INPUT),
            ],
            capture_output=True,
            text=True,
        )
        if result.returncode != 0:
            print(result.stderr, file=sys.stderr)
            return result.returncode
        payload = json.loads(report.read_text(encoding="utf-8"))

    pins = sorted(
        {
            (item["metadata"]["name"].lower(), item["metadata"]["version"])
            for item in payload.get("install", [])
        }
    )
    OUTPUT.write_text(HEADER + "".join(f"{name}=={version}\n" for name, version in pins), encoding="utf-8")
    print(f"wrote {OUTPUT.name} with {len(pins)} pinned packages")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
